const D = { energy:.6, scale:1, density:.5, speed:1, hue:34, fold:6, phason:.5, front:.55, x:.5, y:.5, style:'plaster', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const trb  = (S.tb = (S.tb||0)*.87 + (A.treble||0)*.13);

// ---- de Bruijn multigrid -> dual rhombic quasilattice ---------------------
// N line families at pi/N apart give 2N-fold symmetry: N=6 -> the 12-fold
// dodecagonal tiling (30/60/90 rhombi), N=5 -> 10-fold, N=4 -> 8-fold.
const N = cl(Math.round(P.fold), 4, 7)|0;

// gamma_j is the perpendicular-space coordinate. Drifting each family on its
// OWN incommensurate rate is a phason: tiles flip in place. cam is a genuine
// pan across the (infinite, never-repeating) tiling.
S.pz = (S.pz||0) + dt*sp*(.010 + .085*cl(P.phason,0,1));
S.cx = (S.cx||0) + dt*sp*(.20 + .16*Math.sin(K.t*.041));
S.cy = (S.cy||0) + dt*sp*(.11 + .16*Math.cos(K.t*.053+1.4));
const rot = K.t*.0115*sp + .07*Math.sin(K.t*.0637+2.1);

const EX=[], EY=[], G=[];
let vox=0, voy=0;
for (let j=0;j<N;j++){
  const a = Math.PI*j/N;
  EX[j] = Math.cos(a); EY[j] = Math.sin(a);
  G[j] = fr(j*7.13+1.9)*3.1 + S.pz*(1 + .37*fr(j*11.7+.3));
  vox += (G[j]+.5)*EX[j]; voy += (G[j]+.5)*EY[j];
}

const ax = cl(P.x,.15,.85)*width, ay = cl(P.y,.15,.85)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));
// tile count grows as Rv^2; floor the edge length so the frame is always fully
// covered without blowing past the shape budget (Rv<=11 -> <=~570 rhombi)
const te = Math.max(u*.15*cl(P.scale,.75,2.2), corner/9.4);
const Rv = corner/te + 1.6;
// v ~= (N/2)*p - sum (gamma_m+.5) e_m  ->  invert to find the p-disc we need
const pcx = 2*(S.cx + vox)/N, pcy = 2*(S.cy + voy)/N;
const Rp = 2*(Rv + 3.2)/N;

const TL = [], TLMAX = 3600;                               // 6 slots per tile -> 600 rhombi
for (let j=0;j<N && TL.length<TLMAX;j++){
  for (let jp=j+1;jp<N && TL.length<TLMAX;jp++){
    const cx=EX[j], cy=EY[j], dx=EX[jp], dy=EY[jp];
    const det = cx*dy - cy*dx;
    if (Math.abs(det) < 1e-6) continue;
    const bj = pcx*cx + pcy*cy - G[j], bp = pcx*dx + pcy*dy - G[jp];
    const k0 = Math.ceil(bj-Rp), k1 = Math.floor(bj+Rp);
    const q0 = Math.ceil(bp-Rp), q1 = Math.floor(bp+Rp);
    for (let k=k0;k<=k1 && TL.length<TLMAX;k++){
      const a = k + G[j];
      for (let q=q0;q<=q1 && TL.length<TLMAX;q++){
        const b = q + G[jp];
        const px = (a*dy - b*cy)/det, py = (cx*b - dx*a)/det;
        const rx = px-pcx, ry = py-pcy;
        if (rx*rx + ry*ry > Rp*Rp) continue;
        let ox=0, oy=0;
        for (let m=0;m<N;m++){
          const Km = (m===j) ? k-1 : (m===jp) ? q-1 : Math.floor(px*EX[m] + py*EY[m] - G[m]);
          ox += Km*EX[m]; oy += Km*EY[m];
        }
        const mx = ox + (cx+dx)*.5 - S.cx, my = oy + (cy+dy)*.5 - S.cy;
        if (mx*mx + my*my > (Rv+1)*(Rv+1)) continue;
        let kind = jp-j; if (kind > N-kind) kind = N-kind;
        TL.push(ox - S.cx, oy - S.cy, j, jp, kind, Math.abs(det));
      }
    }
  }
}

// ---- style tables ---------------------------------------------------------
const wire = (sty==='xray');
function grd(){
  if (sty==='lapis')   return [236, 74, 12];
  if (sty==='steel')   return [206, 16, 13];
  if (wire)            return [(H+188)%360, 60, 4];
  if (sty==='pigment') return [46, 12, 92];
  return [(H+8)%360, 26, 12];                                // plaster: shadowed niche
}
// base tone per rhombus kind (1 = thinnest)
function kindTone(kind){
  const q = (kind-1)/Math.max(1, Math.floor(N/2)-1);
  if (sty==='lapis')   return [ (H + 4 + q*16)%360, 30 - q*16, 62 + q*30 ];
  if (sty==='steel')   return [ 206 + q*10, 8 + q*5, 36 + q*24 ];
  if (wire)            return [ (H + 150 + q*70)%360, 40, 96 ];
  if (sty==='pigment') return [ [352, 205, 46][kind % 3], 62, 84 ];
  return [ (H + 2 + q*10)%360, 20 - q*6, 46 + q*24 ];        // plaster
}

// ---- ground ---------------------------------------------------------------
const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);

// ---- orbiting raking light + the annealing front --------------------------
const lang = K.t*.083*sp + .5*Math.sin(K.t*.0311);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const plx = (.5 + .27*Math.sin(K.t*.061+.3))*width, ply = (.5 + .24*Math.cos(K.t*.047+2.2))*height;
const fdir = K.t*.037*sp + 1.1;
const fnx = Math.cos(fdir), fny = Math.sin(fdir);
const fw = cl(P.front,0,1)*(.65+.5*lift);

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND);
const jw = (u/900)*(.5 + 2.2*(1-cl(P.density,0,1))*.35 + 1.1*en);
const hatch = cl(P.density,0,1) > .18 && TL.length < 2520;  // budget: hatch only while the rhombi are big enough to read

for (let i=0;i<TL.length;i+=6){
  const ox=TL[i], oy=TL[i+1], j=TL[i+2], jp=TL[i+3], kind=TL[i+4], ar=TL[i+5];
  const e0x=EX[j], e0y=EY[j], e1x=EX[jp], e1y=EY[jp];
  const cxm = ox + (e0x+e1x)*.5, cym = oy + (e0y+e1y)*.5;

  // flat shade: long diagonal against the orbiting light
  let dgx = e0x+e1x, dgy = e0y+e1y;
  const dl = Math.hypot(dgx,dgy) || 1; dgx/=dl; dgy/=dl;
  const lam = Math.abs(dgx*lgx + dgy*lgy);
  // annealing front: a narrow travelling band of relaxation
  const wv = Math.sin((cxm*fnx + cym*fny)*.44 - K.t*1.09*sp) * .5 + .5;
  const fq = fw * Math.pow(wv, 4) * (.6 + .55*bass);
  const t0 = kindTone(kind);
  const sh = (.34 + .60*lam) * (.62 + .5*en) + fq*.85 + .10*Math.sin(cxm*.7+cym*.5);

  const X0=ox*te, Y0=oy*te, X1=(ox+e0x)*te, Y1=(oy+e0y)*te;
  const X2=(ox+e0x+e1x)*te, Y2=(oy+e0y+e1y)*te, X3=(ox+e1x)*te, Y3=(oy+e1y)*te;

  if (wire) {
    noFill();
    stroke(t0[0], t0[1], cl(t0[2]*(.30+.62*sh+.3*trb),0,100), cl(26 + 52*sh, 8, 92));
    strokeWeight(jw*(.7+1.1*sh));
    quad(X0,Y0,X1,Y1,X2,Y2,X3,Y3);
    if (hatch && kind >= 2) {
      stroke(t0[0], t0[1], t0[2], cl(10+26*sh,0,60)); strokeWeight(jw*.5);
      line((X0+X1)*.5, (Y0+Y1)*.5, (X2+X3)*.5, (Y2+Y3)*.5);
    }
  } else {
    fill(t0[0], cl(t0[1]*(1.18-.35*sh),0,100), cl(t0[2]*(.30 + .78*sh), 2, 100));
    stroke(gc[0], cl(gc[1]*1.2,0,100), cl(gc[2]*(.5 + .5*(1-en)), 0, 100), 74);
    strokeWeight(jw);
    quad(X0,Y0,X1,Y1,X2,Y2,X3,Y3);
    if (hatch && kind >= 2 && ar > .45) {           // engraved hatching on the fat tiles
      const nh = 2 + ((kind*7+j)%2);
      stroke(t0[0], cl(t0[1]+16,0,100), cl(t0[2]*(.30+.5*sh)*.62, 0, 100), 30 + 40*cl(P.density,0,1));
      strokeWeight(jw*.55);
      for (let h=1;h<=nh;h++){
        const f = h/(nh+1);
        line(X0 + (X3-X0)*f, Y0 + (Y3-Y0)*f, X1 + (X2-X1)*f, Y1 + (Y2-Y1)*f);
      }
    }
  }
}
pop();

// ---- cached grain / plaster tooth ----------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=440, th=290, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2400;i++){
    const rr = .4 + fr(i*4.77)*1.9;
    t.fill(30, 8, 100 - fr(i*6.31)*46, 52);
    t.ellipse(fr(i*2.11)*tw, fr(i*3.97+4.4)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

// ---- moving chiaroscuro: sink the plate, then relight with a wandering pool.
// (a bare additive pool over the whole frame washes the mean luminance up past
// the 0.5 target and toward the 0.92 ceiling -- darken first, relight second.)
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (24 + 30*en));
L.blendMode(ADD);
const bx2 = plx/width*lw2, by2 = ply/height*lh2;
for (let i=0;i<9;i++){
  const q2=i/8, rr = Math.max(lw2,lh2)*(1.24 - q2*.96);
  L.fill(0, 0, 100, (6 + 7.5*en + 5*bass)*(.26 + .74*q2*q2));
  L.ellipse(bx2, by2, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
